/* A planted world of colored spheres; growth happens in local plant coordinates. */
function createParticleGarden(){let seed=82;const random=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296},plants=[],ground=[];const colors={mint:[127,206,164],teal:[111,206,203],violet:[175,143,218],rose:[229,150,180],coral:[230,162,132],gold:[229,202,119],cream:[222,225,195]};const names=['Lavender','Rose cosmos','Golden bloom','Jade fern','Coral lily','Silver daisy','Turquoise fern'];
for(let i=0;i<19;i++){const a=i*2.39996323,r=i===0?0:.45+Math.sqrt(i/19)*1.03,type=i%7,points=[],baseH=.55+random()*.42,plant={name:names[type],type,x:Math.cos(a)*r,z:Math.sin(a)*r,height:baseH,growth:.8+random()*.3,target:1,phase:random()*6.28,points};plant.target=plant.growth;
const add=(x,y,z,color,size=.8)=>points.push({x,y,z,color,size});
for(let j=0;j<180;j++){const t=j/179;for(let k=0;k<3;k++){const angle=k/3*6.28;add(Math.cos(angle)*.012,t*baseH,Math.sin(angle)*.012,colors.mint,.65)}}
for(let leaf=0;leaf<5;leaf++){const side=leaf%2?-1:1,angle=leaf*2.4;for(let j=0;j<95;j++){const t=random(),width=Math.sin(t*Math.PI)*.075*(random()*2-1),length=.16+leaf*.012;add(Math.cos(angle)*length*t+Math.sin(angle)*width,baseH*(.18+leaf*.12)+Math.sin(t*Math.PI)*.055,Math.sin(angle)*length*t-Math.cos(angle)*width,leaf%2?colors.teal:colors.mint,.65)}}
if(type===3||type===6){for(let frond=0;frond<9;frond++){const angle=frond/9*6.28;for(let j=0;j<120;j++){const t=random(),side=j%2?1:-1,width=Math.sin(t*Math.PI)*.11*random()*side,rad=.39*t;add(Math.cos(angle)*rad+Math.sin(angle)*width,baseH*.45+Math.sin(t*Math.PI*.82)*baseH*.68,Math.sin(angle)*rad-Math.cos(angle)*width,type===3?colors.mint:colors.teal,.7)}}}
else if(type===0){for(let spire=0;spire<5;spire++){const angle=spire*2.4;for(let j=0;j<160;j++){const t=random(),theta=random()*6.28,rr=.04*Math.sin(t*Math.PI)+.018;add(Math.cos(angle)*.09+Math.cos(theta)*rr,baseH*.6+t*.48,Math.sin(angle)*.09+Math.sin(theta)*rr,colors.violet,.85)}}}
else{const color=[colors.violet,colors.rose,colors.gold,colors.mint,colors.coral,colors.cream][type],petals=type===5?11:7;for(let petal=0;petal<petals;petal++){const angle=petal/petals*6.28;for(let j=0;j<95;j++){const t=random(),r=.05+t*.24,width=Math.sin(t*Math.PI)*(.055+random()*.025)*(random()*2-1);add(Math.cos(angle)*r+Math.sin(angle)*width,baseH+Math.sin(t*Math.PI)*.08-t*.035+(random()-.5)*.015,Math.sin(angle)*r-Math.cos(angle)*width,color,.9)}}for(let j=0;j<140;j++){const angle=random()*6.28,r=Math.sqrt(random())*.065;add(Math.cos(angle)*r,baseH+.027+random()*.025,Math.sin(angle)*r,colors.gold,.85)}}plant.maxY=Math.max(...points.map(p=>p.y));plants.push(plant)}
for(let i=0;i<3200;i++){const a=random()*6.28,r=Math.sqrt(random())*1.9;ground.push({x:Math.cos(a)*r,y:-.035-random()*.09,z:Math.sin(a)*r,size:.45+random()*.45,color:i%5===0?[139,166,130]:[76,117,102]})}return{plants,ground}}
(()=>{const canvas=document.getElementById('particleGarden');if(!canvas)return;const ctx=canvas.getContext('2d'),status=document.getElementById('gardenStatus'),controls=document.querySelector('.garden-plants'),reduce=matchMedia('(prefers-reduced-motion: reduce)').matches,{plants,ground}=createParticleGarden();let w=0,h=0,scale=1,yaw=.1,pitch=0,velocity=0,selected=0,time=0,last=0,raf=0,visible=false,dragging=false,moved=0,lastX=0,lastY=0,hover=-1,hits=[];
function grow(i){selected=i;const p=plants[i];p.target=Math.min(2.15,p.target+.3);p.pulse=1;status.textContent=p.name+(p.target>=2.15?' is in full bloom.':' is growing.');queue()}
plants.forEach((p,i)=>{const b=document.createElement('button');b.textContent=`Grow ${p.name} ${Math.floor(i/7)+1}`;b.onclick=()=>grow(i);controls.append(b)});
function resizeGarden(){const r=canvas.getBoundingClientRect();w=r.width;h=r.height;const d=Math.min(devicePixelRatio||1,2);canvas.width=w*d;canvas.height=h*d;ctx.setTransform(d,0,0,d,0,0);scale=Math.min(w*.22,h*.29);queue()}
function project(x,y,z){y-=.5;const cy=Math.cos(yaw),sy=Math.sin(yaw),xx=x*cy+z*sy,zz=-x*sy+z*cy,yy=y*Math.cos(pitch)-zz*Math.sin(pitch),depth=y*Math.sin(pitch)+zz*Math.cos(pitch),perspective=6/(6+depth);return{x:w*.5+xx*scale*perspective,y:h*.58-yy*scale*perspective,z:depth,p:perspective}}
function pick(x,y){let best=-1,score=1e9;for(const hit of hits){const dx=x-hit.x,dy=y-hit.y,d=Math.hypot(dx,dy);if(d<hit.radius&&d/(hit.radius*.7)<score){score=d/(hit.radius*.7);best=hit.index}}return best}
function frame(now){raf=0;if(!visible)return;const dt=Math.min(.04,(now-(last||now-16))/1000);last=now;if(!reduce)time+=dt;if(!dragging){yaw+=velocity*dt+(reduce?0:.017*dt);velocity*=Math.exp(-3*dt)}const tallest=Math.max(...plants.map(p=>p.maxY*p.growth)),fit=Math.min(w*.22,h*.29)/(1+Math.max(0,tallest-1.45)*.4);scale+=(fit-scale)*(1-Math.exp(-dt*2.8));let growing=false;const sprites=[];hits=[];
for(const p of ground){const q=project(p.x,p.y,p.z);sprites.push({...q,size:p.size,color:p.color,alpha:.51})}
plants.forEach((plant,index)=>{const delta=plant.target-plant.growth;if(Math.abs(delta)>.0005){plant.growth+=delta*(1-Math.exp(-dt*2.4));growing=true}else plant.growth=plant.target;plant.pulse=(plant.pulse||0)*Math.exp(-dt*1.5);const growth=plant.growth,spread=Math.sqrt(growth),sway=reduce?0:Math.sin(time*.85+plant.phase)*.025,top=project(plant.x,plant.height*growth*.8,plant.z),radius=Math.max(24,.37*spread*scale*top.p);hits.push({index,x:top.x,y:top.y,radius});
for(const point of plant.points){const y=point.y*growth,x=plant.x+point.x*spread+sway*y*y,z=plant.z+point.z*spread+Math.cos(time*.7+plant.phase)*.008*y,q=project(x,y,z),highlight=(index===hover?.16:0)+plant.pulse*.3;sprites.push({...q,size:point.size*(1+plant.pulse*.12),color:point.color,alpha:Math.min(.98,.69+(1-q.z)*.07+highlight)})}});
sprites.sort((a,b)=>b.z-a.z);ctx.clearRect(0,0,w,h);for(const s of sprites){const radius=Math.max(.4,s.size*s.p*1.08);ctx.fillStyle=`rgba(${s.color[0]},${s.color[1]},${s.color[2]},${s.alpha})`;ctx.beginPath();ctx.arc(s.x,s.y,radius,0,Math.PI*2);ctx.fill()}
if(!reduce||growing||Math.abs(velocity)>.001||plants.some(p=>p.pulse>.005))queue()}
function queue(){if(!raf)raf=requestAnimationFrame(frame)}
canvas.addEventListener('pointerdown',e=>{dragging=true;moved=0;lastX=e.clientX;lastY=e.clientY;canvas.setPointerCapture(e.pointerId);canvas.classList.add('dragging')});canvas.addEventListener('pointermove',e=>{const r=canvas.getBoundingClientRect();hover=pick(e.clientX-r.left,e.clientY-r.top);if(dragging){const dx=e.clientX-lastX,dy=e.clientY-lastY;moved+=Math.abs(dx)+Math.abs(dy);yaw+=dx*.006;pitch=Math.max(-.65,Math.min(.85,pitch+dy*.002));velocity=dx*.055;lastX=e.clientX;lastY=e.clientY}else canvas.style.cursor=hover>=0?'pointer':'grab';queue()});canvas.addEventListener('pointerup',e=>{dragging=false;canvas.classList.remove('dragging');if(moved<8){const r=canvas.getBoundingClientRect(),i=pick(e.clientX-r.left,e.clientY-r.top);if(i>=0)grow(i)}});canvas.addEventListener('pointercancel',()=>{dragging=false;canvas.classList.remove('dragging')});canvas.addEventListener('pointerleave',()=>{hover=-1});canvas.addEventListener('keydown',e=>{if([' ','Enter','ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();if(e.key===' '||e.key==='Enter')grow(selected);else if(e.key==='ArrowLeft')yaw-=.15;else if(e.key==='ArrowRight')yaw+=.15;else pitch=Math.max(-.65,Math.min(.85,pitch+(e.key==='ArrowUp'?.08:-.08)));queue()}});new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;last=0;if(visible)queue()},{rootMargin:'150px'}).observe(canvas);addEventListener('resize',resizeGarden);resizeGarden();})();
